import{_ as t,o as s,c as o,a0 as r}from"./chunks/framework.ChlVJx0I.js";const i="/pi-extensions/assets/resources.CzA_XxMH.png",m=JSON.parse('{"title":"resource-toggle extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/resource-toggle.md","filePath":"extensions/resource-toggle.md","lastUpdated":1789775493000}'),n={name:"extensions/resource-toggle.md"};function a(l,e,c,d,h,g){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="resource-toggle-extension" tabindex="-1">resource-toggle extension <a class="header-anchor" href="#resource-toggle-extension" aria-label="Permalink to &quot;resource-toggle extension&quot;">​</a></h1><p>Enable and disable extensions, skills, prompt templates, and themes from inside a running session, without editing settings files by hand.</p><ul><li><code>/resources</code> opens the interactive list in TUI mode (a text table in the headless modes).</li><li><code>/enable &lt;name&gt;</code>, <code>/disable &lt;name&gt;</code>, and <code>/inherit &lt;name&gt;</code> change the state of one named resource; <code>--project</code> selects project mode, <code>--global</code> is the default.</li><li>The <code>resource_toggle</code> tool lets the agent list resources and apply changes on request; with no arguments it opens the interactive list.</li></ul><p>State lives in pi&#39;s native settings override patterns - the same files and the same format <code>pi config</code> uses (<a href="/pi-extensions/adr/0012-resource-toggles-write-native-settings-patterns.html">ADR 0012</a>). The commands and <code>pi config</code> are interchangeable: a change made in one shows up in the other.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The interactive list with the fixture resource set, grouped by type. The checkbox shows the state in the current mode; the <code>usage</code> extension is disabled by a settings pattern, so its box is empty.</p><p><img src="'+i+'" alt="resource list TUI"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Write modes.</strong> Global mode writes the global settings (<code>&lt;agent dir&gt;/settings.json</code>); project mode writes the project settings (<code>&lt;cwd&gt;/.pi/settings.json</code>). A project resource can be overridden in project mode; <code>inherit</code> clears that override so the resource returns to the global state. <code>inherit</code> has no global mode.</li><li><strong>Immediate effect.</strong> Every change flushes the settings and reloads the session, so the change applies at once and survives a restart. The reload rebinds every extension, so the in-session state of other extensions resets.</li><li><strong>Self-guard.</strong> The extension refuses to disable or clear itself: doing so would remove the toggle commands from the session.</li><li><strong>Name matching.</strong> A name may be a display name, a unique name prefix, or a path fragment. A name that matches several resources is reported as ambiguous with the candidates listed; a name that matches none is reported as not found.</li><li><strong>Trusted projects only.</strong> Project mode requires a trusted project; in an untrusted project the TUI shows the restriction and project commands are refused.</li><li><strong>Headless modes.</strong> In print and RPC modes <code>/resources</code> prints the table and the state commands work with a console report; the interactive list is TUI mode only.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Installing or removing resources (enabling and disabling only).</li><li>Per-session (non-persisted) toggles: every change is written to settings.</li><li>Toggling pi&#39;s built-in tools. The <a href="/pi-extensions/extensions/tools.html">tools extension</a> covers built-in tools.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>tests/resource-toggle/matcher.test.ts</code> - name matching and ambiguity.</li><li><code>tests/resource-toggle/resolver.test.ts</code> - resource discovery across scopes.</li><li><code>tests/resource-toggle/state-machine.test.ts</code> - the pattern transitions for enable, disable, and inherit in both write modes.</li><li><code>tests/resource-toggle/tui.test.ts</code> - the interactive list rendering.</li><li><code>npm run e2e:resource-toggle</code> - a real pi RPC session: list, toggle, reload, and the self-guard.</li></ul>',13)])])}const p=t(n,[["render",a]]);export{m as __pageData,p as default};
